def minRunesToAdd(n, crystals, flowFrom, flowTo):
    # Build the graph
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in zip(flowFrom, flowTo):
        graph[u].append(v)

    # Use BFS to find all nodes reachable from crystals
    visited = [False] * n
    queue = deque(crystals)
    for c in crystals:
        visited[c] = True

    while queue:
        node = queue.popleft()
        for nei in graph[node]:
            if not visited[nei]:
                visited[nei] = True
                queue.append(nei)

    # Marks every node reachable from u
    def dfs(u, mark):
        stack = [u]
        while stack:
            node = stack.pop()
            mark[node] = True
            for nei in graph[node]:
                if not mark[nei]:
                    stack.append(nei)

    # Finishing order of a DFS over the nodes not reached from crystals
    seen = visited[:]
    order = []
    for s in range(n):
        if seen[s]:
            continue
        seen[s] = True
        stack = [(s, iter(graph[s]))]
        while stack:
            u, it = stack[-1]
            for v in it:
                if not seen[v]:
                    seen[v] = True
                    stack.append((v, iter(graph[v])))
                    break
            else:
                order.append(u)
                stack.pop()

    # Each unmarked node, taken in decreasing finishing time, starts a source SCC
    result = 0
    mark = visited[:]
    for u in reversed(order):
        if not mark[u]:
            dfs(u, mark)
            result += 1

    return result
